set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import json,base64,shutil,ast
payload=json.loads('{"rag/service/baidu_maps.py": "", "rag/service/route_plan.py": "", "rag/service/travel_agent.py": "", "rag/service/retrieval_server.py": "", "rag/eval/tests/test_baidu_maps.py": ""}')
backup=Path('deploy/backups/baidu-maps-v1');backup.mkdir(parents=True,exist_ok=True)
for n,b in payload.items():
 p=Path(n)
 if p.exists() and n.startswith('rag/service/') and not (backup/p.name).exists():shutil.copyfile(p,backup/p.name)
 if p.name=='retrieval_server.py':
  def funcs(s):return {v.name:ast.dump(v,include_attributes=False) for v in ast.parse(s).body if isinstance(v,ast.FunctionDef)}
  old=funcs(p.read_text());new=funcs(base64.b64decode(b).decode())
  for key in ('ask_api','search_api','plan_api'):assert old[key]==new[key],key
 p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(base64.b64decode(b))
PY
PYTHONPATH=rag .venv/bin/python -m unittest discover -s rag/eval/tests -p 'test_*.py'
PYTHONPATH=rag .venv/bin/python - <<'PY'
from service.baidu_maps import BaiduMaps
from pathlib import Path
import json
p={'lat':34.63,'lng':112.45,'coord_type':'bd09ll'};q={'lat':34.555862,'lng':112.485337,'coord_type':'bd09ll'}
cases=[('search',{'query':'洛阳博物馆'}),('suggest',{'query':'洛阳博物馆'}),('geocode',{'address':'洛阳市洛龙区聂泰路洛阳博物馆'}),('reverse',{'point':p})]+[('route',{'origin':p,'destination':q,'mode':mode}) for mode in ('driving','walking','riding','transit')]+[('route',{'origin':p,'destination':q,'advanced':True}),('matrix',{'origins':[p],'destinations':[q]}),('convert',{'points':[p],'target':'gcj02'})]
out=[];api=BaiduMaps()
for action,args in cases:
 result=api.query(action,args);out.append({'action':action,'arguments':args,'result':result});print(action,args.get('mode',args.get('advanced','')),result['state'],result.get('reason'),flush=True)
 Path('rag/eval/reports/baidu_maps_provider_probe.json').write_text(json.dumps(out,ensure_ascii=False,indent=2))
PY
